// One run of one implementation, from the command line, mirroring the Java runner: one engine to a
// process, the rate offered rather than requested, and every artifact written where analyze.py
// reads it. This side has no generator and never will (one generator exists, and neither language
// owns it), so the input is always a MEFLOW01 log: generated by the Java side, or a real session
// converted by matching-calibration.

#include <cstdint>
#include <cstdio>
#include <fstream>
#include <iostream>
#include <map>
#include <memory>
#include <sstream>
#include <string>
#include <vector>

#include "benchmarks/decode_only_engine.hpp"
#include "benchmarks/environment.hpp"
#include "benchmarks/manifest.hpp"
#include "benchmarks/measurement.hpp"
#include "benchmarks/run.hpp"
#include "indexed/indexed_engine.hpp"
#include "io_github_giovanicaprison_matching_protocol/MessageHeader.h"
#include "lean-naive/lean_engine.hpp"
#include "naive/naive_engine.hpp"

namespace {

namespace matching = io::github::giovanicaprison::matching;
namespace benchmarks = matching::benchmarks;

// The engines this binary can be, by name. No reflection in this language, so the registry is the
// list, and a rung arriving means one line here.
benchmarks::Measurement::EngineFactory factoryOf(const std::string& name) {
  if (name == "naive") {
    return [](matching::api::EventPublisher& events) {
      return std::make_unique<matching::naive::NaiveEngine>(events);
    };
  }
  if (name == "indexed") {
    return [](matching::api::EventPublisher& events) {
      return std::make_unique<matching::indexed::IndexedEngine>(events);
    };
  }
  if (name == "lean-naive") {
    return [](matching::api::EventPublisher& events) {
      return std::make_unique<matching::lean::naive::LeanEngine>(events);
    };
  }
  if (name == "decode") {
    return [](matching::api::EventPublisher&) {
      return std::make_unique<benchmarks::DecodeOnlyEngine>();
    };
  }
  throw std::invalid_argument(name + " is not an implementation this binary carries");
}

benchmarks::Cores coresOf(const std::string& cores) {
  if (cores.empty()) {
    return benchmarks::Cores{};
  }
  benchmarks::Cores parsed;
  if (std::sscanf(cores.c_str(), "%d,%d,%d", &parsed.driver, &parsed.engine, &parsed.verifier) !=
      3) {
    throw std::invalid_argument("--cores wants three, driver first: " + cores);
  }
  return parsed;
}

std::vector<benchmarks::Counter> countersOf(const std::string& names) {
  if (names.empty()) {
    return benchmarks::counters::few();
  }
  std::vector<benchmarks::Counter> wanted;
  std::string name;
  std::istringstream stream(names);
  while (std::getline(stream, name, ',')) {
    const auto counter = benchmarks::counters::byName(name);
    if (!counter.has_value()) {
      throw std::invalid_argument(name + " is not a counter the catalogue names");
    }
    wanted.push_back(*counter);
  }
  return wanted;
}

// One byte per recorded command saying what the command was, for the per-type attribution.
void writeTypes(const benchmarks::Run& run, const matching::conformance::CommandLog& log) {
  std::ofstream out(run.file("types.bin"), std::ios::binary);
  out.write("METYPES1", 8);
  const std::int32_t recorded = static_cast<std::int32_t>(log.count() - log.measuredFrom);
  out.write(reinterpret_cast<const char*>(&recorded), sizeof(recorded));
  matching::protocol::MessageHeader header;
  for (std::size_t command = log.measuredFrom; command < log.count(); command++) {
    header.wrap(const_cast<char*>(log.buffer.data()), log.offsets[command], 0,
                log.offsets[command] + log.lengths[command]);
    const char type = static_cast<char>(header.templateId());
    out.write(&type, 1);
  }
}

std::string argument(const int count, char** arguments, const std::string& name,
                     const std::string& fallback) {
  for (int at = 1; at + 1 < count; at += 2) {
    if (name == arguments[at]) {
      return arguments[at + 1];
    }
  }
  return fallback;
}

}  // namespace

int main(const int count, char** arguments) {
  const std::string implementation = argument(count, arguments, "--implementation", "");
  const std::string logFile = argument(count, arguments, "--log", "");
  if (implementation.empty() || logFile.empty()) {
    std::cerr << "usage: benchmarks --implementation naive|indexed|lean-naive|decode --log FILE"
              << " [--label L] [--rate N] [--warmup N] [--cores a,b,c] [--counters NAMES]"
              << " [--results DIR]\n";
    return 2;
  }
  const std::string label = argument(count, arguments, "--label", implementation + "-cpp");

  const matching::conformance::CommandLog log =
      matching::conformance::CommandLog::readFrom(logFile);

  benchmarks::Parameters parameters;
  parameters.ratePerSecond = std::stoll(argument(count, arguments, "--rate", "100000"));
  parameters.compilationWarmup =
      static_cast<std::size_t>(std::stoll(argument(count, arguments, "--warmup", "200000")));
  parameters.cores = coresOf(argument(count, arguments, "--cores", ""));
  parameters.counters = countersOf(argument(count, arguments, "--counters", ""));

  const benchmarks::Run run =
      benchmarks::Run::create(argument(count, arguments, "--results", "results"), label);
  const benchmarks::Environment environment = benchmarks::Environment::ofThisMachine();
  std::string commandLine;
  for (int at = 0; at < count; at++) {
    commandLine += (at == 0 ? "" : " ") + std::string(arguments[at]);
  }
  const benchmarks::Manifest manifest{
      run,
      implementation,
      commandLine,
      environment,
      parameters.cores.engine == benchmarks::Cores::UNPINNED
          ? std::vector<benchmarks::Setting>{benchmarks::Setting::required("engine core", "cores",
                                                                           "chosen", std::nullopt)}
          : environment.isolationOf(parameters.cores.engine),
      logFile,
      log.count()};
  manifest.write();

  const benchmarks::Measurement::Outcome outcome =
      benchmarks::Measurement::run(log, factoryOf(implementation), parameters);
  outcome.writeTo(run.directory);
  writeTypes(run, log);

  std::printf("run          %s\n", run.id.c_str());
  std::printf("grade        %s\n", manifest.grade().c_str());
  std::printf("unmet        %zu of %zu settings\n", environment.failures(),
              environment.settings().size());
  std::printf("offered      %lld a second\n", static_cast<long long>(parameters.ratePerSecond));
  std::printf("harness      %s\n", outcome.harnessKeptUp() ? "kept up" : "fell behind");
  std::printf("events       %llu\n",
              static_cast<unsigned long long>(outcome.verification.events()));
  std::printf(
      "service      p50 %lld  p99 %lld  p999 %lld  max %lld ns\n",
      static_cast<long long>(outcome.service.p50), static_cast<long long>(outcome.service.p99),
      static_cast<long long>(outcome.service.p999), static_cast<long long>(outcome.service.max));
  std::printf(
      "response     p50 %lld  p99 %lld  p999 %lld  max %lld ns\n",
      static_cast<long long>(outcome.response.p50), static_cast<long long>(outcome.response.p99),
      static_cast<long long>(outcome.response.p999), static_cast<long long>(outcome.response.max));
  std::printf("artifacts    %s\n", run.directory.string().c_str());
  return 0;
}
